            'real work must never be filtered');
        assert.notOk(gitStaging.isRuntimeArtifactStatusLine('?? factory-kit/'),
            'factory-kit has its own filter');
        assert.notOk(gitStaging.isRuntimeArtifactStatusLine('M  js/smAgent.js'),
            'real work must never be filtered');
