                if (args.command === 'git branch --show-current') return 'ai/TS-1305\n';
                return '';
            }
        });

        var result = loaded.mod.action({
            ticket: {
                key: 'TS-1305',
                fields: { summary: 'runtime-only status noise', description: '', labels: [] }
